-- PixelRP: the Asthorine set, in Builders > Customs > Asthorine.
--
-- The whole Asthorine set on ONE page under the existing Customs category,
-- beside Exterior Modern. Generated by docker/nitro/import-pack-tree.py.
--
-- The download is 65 bundles. 17 of them - the doors and windows - were
-- already imported by 94_CustomsFurni onto Medieval Doors, and are kept as
-- they are (their bundles, ids and names untouched): the epilogue only moves
-- their catalog rows here, so the set reads as one page. The other 48
-- are new.
--
-- The pack carries no names, so the new titles come from the classnames
-- ('Painting 11', 'Door 6 1x 2'); the 17 keep the names 94 gave them.
--
-- The rendering half is the .nitro bundles, the icons and the FurnitureData
-- entries under nitro/overrides/; the rows below are inert without them.
--
-- Everything is free - the catalog has been since 90_FreeCatalog.
--
-- Idempotent: fixed id ranges, cleared before insert. The 17 moved pieces are
-- addressed by id, and the sets under Customs are renumbered alphabetically,
-- so a re-run lands the same way.

SET @builders := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `caption` = 'Builders' LIMIT 1),
    912362);
SET @customs := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `id` = 944000 LIMIT 1),
    (SELECT `id` FROM `catalog_pages` WHERE `caption` = 'Customs' AND `parent_id` = @builders
        ORDER BY `id` LIMIT 1));

DELETE FROM `catalog_items` WHERE `item_id` BETWEEN 110600 AND 110647;
DELETE FROM `catalog_pages` WHERE `id` BETWEEN 951000 AND 951999;
DELETE FROM `furniture` WHERE `id` BETWEEN 110600 AND 110647;

     `page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`)
VALUES
    (951000, @customs, 'Asthorine', 193, 2, 0, 1, '', 'default_3x3', '', '', b'1', b'1');


-- Furniture. id == sprite_id, the convention every custom line here follows;
-- interaction_modes_count is the bundle's own animation count.


UPDATE `catalog_items` SET `page_id` = 951000
    WHERE `page_id` = 944065 AND `item_id` IN ('106095','106096','106097','106098','106099','106100','106101','106102','106103','106104','106105','106106','106107','106108','106109','106110','106111');
UPDATE `catalog_pages` SET `visible` = b'0', `enabled` = b'0'
    WHERE `id` = 944065 AND `caption` = 'Medieval Doors'
    AND NOT EXISTS (SELECT 1 FROM (SELECT `page_id` FROM `catalog_items`) AS `ci` WHERE `ci`.`page_id` = 944065);
SET @n := 0;
UPDATE `catalog_pages` SET `order_num` = (@n := @n + 1)
    WHERE `parent_id` = @customs
    ORDER BY `caption`;
